<?php
// Контроллеры в Laravel — это классы, которые обрабатывают HTTP-запросы и возвращают HTTP-ответы. Они служат посредниками между маршрутами и логикой приложения, обеспечивая организацию кода и повторное использование функциональности. Контроллеры помогают разделять логику обработки запросов от маршрутов, что делает код более чистым и поддерживаемым.
namespace App\Http\Controllers;

class PageController extends Controller
// указывает где находится класс extends Controller, в данном случае в папке app/Http/Controllers
{
    private function news(): array // prvate обозначает что метод news() доступен только внутри класса PageController, а не из других классов. array указывает что метод возвращает массив
    // внутри список новостей, каждая новость это массив с ключами id, title, category, date и text. Метод news() возвращает массив всех новостей.
    {
        return [
            ['id' => 1, 'title' => 'Анонсирован сиквел популярной приключенческой RPG', 'category' => 'PC', 'date' => '12.10.2026', 'text' => 'Разработчики показали первый трейлер и рассказали о новой боевой системе.'],
            ['id' => 2, 'title' => 'Новая консоль получит эксклюзивный шутер на старте продаж', 'category' => 'Консоли', 'date' => '11.10.2026', 'text' => 'Студия подтвердила, что игра выйдет одновременно с запуском платформы.'],
            ['id' => 3, 'title' => 'Российская команда выиграла международный турнир по CS', 'category' => 'Киберспорт', 'date' => '10.10.2026', 'text' => 'Финал завершился со счётом 2:1 и собрал рекордную аудиторию зрителей.'],
            ['id' => 4, 'title' => 'Большое обновление добавило в игру новый режим и карты', 'category' => 'PC', 'date' => '09.10.2026', 'text' => 'Патч также исправил десятки ошибок и улучшил производительность.'],
            ['id' => 5, 'title' => 'Мобильная стратегия набрала 10 миллионов загрузок за неделю', 'category' => 'Киберспорт', 'date' => '08.10.2026', 'text' => 'Игра возглавила рейтинги магазинов приложений в нескольких странах.'],
            ['id' => 6, 'title' => 'Инди-платформер получил высокие оценки критиков', 'category' => 'PC', 'date' => '07.10.2026', 'text' => 'Проект небольшой студии удивил оригинальной механикой и атмосферой.'],
        ];
        // фактически метод news() возвращает массив новостей
    }

    public function home() // public обозначает что метод home() доступен из других классов, а не только внутри класса PageController
    {
        // метод home() вызывается при обращении к главной странице сайта. Он возвращает представление (view) 'home' и передает в него массив новостей, полученный из метода news().
        return view('home', ['news' => $this->news()]); // view('home', ['news' => $this->news()]) - это вызов функции view(), которая отвечает за отображение представления (view) в Laravel. В данном случае, она загружает шаблон 'home' и передает в него данные в виде массива, где ключ 'news' содержит результат вызова метода $this->news(), то есть массив новостей. Это позволяет шаблону 'home' получить доступ к списку новостей и отобразить их на веб-странице.
        // view('home', ...) загружает шаблон resources/views/home.blade.php
        //Второй аргумент ['news' => $this->news()] это данные для шаблона. В шаблоне появится переменная $news, в которой лежат все 6 новостей
        //$this->news() вызывает метод news() из этого же класса.
    }
    // метод category() вызывается при обращении к странице категории. Он фильтрует новости по категории 'PC' и возвращает представление (view) 'category', передавая в него имя категории и отфильтрованные новости.
    public function category()
    {
        $name = 'PC'; // имя категории, по которой фильтруются новости
        $news = array_filter($this->news(), fn ($n) => $n['category'] === $name); // array_filter оставляет в массиве только элементы, для которых функция вернула true
        // fn ($n) => $n['category'] === $name это короткая функция: «возьми новость $n и проверь, что её категория равна PC». Строгое сравнение === проверяет и значение, и тип.
        // фактически метод category() фильтрует массив новостей, оставляя только те, у которых категория совпадает с $name ('PC'). Результат сохраняется в переменной $news.
        // $this->news() вызывает метод news() из этого же класса, который возвращает массив всех новостей. array_filter() фильтрует этот массив, оставляя только те новости, у которых категория совпадает с $name ('PC'). Результат сохраняется в переменной $news.
        return view('category', ['name' => $name, 'news' => $news]); // view('category', ['name' => $name, 'news' => $news]) загружает шаблон resources/views/category.blade.php и передает в него данные: имя категории и отфильтрованные новости.
        //В шаблон уходят название категории и отфильтрованные новости.
    }

    public function journalist() // метод journalist() вызывается при обращении к странице журналиста. Он возвращает представление (view) 'journalist'.
    {
        return view('journalist'); // view('journalist') загружает шаблон resources/views/journalist.blade.php. В данном случае, метод не передает никаких данных в шаблон.
    }

    public function admin() // метод admin() вызывается при обращении к странице администратора. Он возвращает представление (view) 'admin', передавая в него массив новостей и массив пользователей.
    {
        // view('admin', [...]) загружает шаблон resources/views/admin.blade.php и передает в него данные: массив новостей и массив пользователей.
        return view('admin', [
            'news' => $this->news(),
            'users' => [
                ['id' => 1, 'name' => 'Иван Петров', 'email' => 'ivan@example.com', 'role' => 'admin'],
                ['id' => 2, 'name' => 'Анна Смирнова', 'email' => 'anna@example.com', 'role' => 'journalist'],
                ['id' => 3, 'name' => 'Олег Иванов', 'email' => 'oleg@example.com', 'role' => 'user'],
            ],
            // фактически метод admin() возвращает представление (view) 'admin' и передает в него массив новостей и массив пользователей. В шаблоне 'admin' можно будет использовать переменные $news и $users для отображения соответствующих данных.
        ]);
    }
}